$:set -euo pipefail
gh auth setup-git
git fetch origin main
git checkout --detach origin/main >/dev/null
DEST='workspaces/shared-conversations/6aec3b14-ad4c-83e8-a6e7-0834eadb34ef/41994534799-1'
TEMP="$(mktemp -d)"
trap 'rm -rf "$TEMP"' EXIT
gh run download 41994534799 --repo BestNameYet/Terminals --name chatgpt-shared-export-final-attestation-41994534799-1 --dir "$TEMP"
node workspaces/extractor-srs-design/acceptance/verify-live-export.js "$DEST" "$TEMP/final-attestation.json" > "$TEMP/audit.json"
node - "$DEST" "$TEMP/final-attestation.json" "$TEMP/audit.json" <<'NODE'
"use strict";
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),crypto=require('node:crypto');
const dir=process.argv[2],att=JSON.parse(fs.readFileSync(process.argv[3])),audit=JSON.parse(fs.readFileSync(process.argv[4]));
const required=['response.html','conversation-raw.json','linear-conversation.json','conversation.json','conversation.md','diagnostics.json','receipt.json','execution.json'];
const get=n=>JSON.parse(fs.readFileSync(path.join(dir,n)));
const visible=get('conversation.json'),linear=get('linear-conversation.json'),diagnostics=get('diagnostics.json'),receipt=get('receipt.json');
assert.equal(audit.status,'PASS');assert.equal(att.verification,'VERIFIED');assert.equal(att.run_id,'41994534799');
assert.equal(required.length,8);
for(const n of required){const b=fs.readFileSync(path.join(dir,n)),h=crypto.createHash('sha256').update(b).digest('hex');const e=att.paths.find(x=>x.path===dir+'/'+n);assert.ok(e,'Missing '+n);assert.equal(e.bytes,b.length);assert.equal(e.sha256,h);assert.equal(e.matched_remote_bytes,true);}
assert.equal(visible.messages.length,visible.counts.user+visible.counts.commentary+visible.counts.final);
assert.equal(linear.records.length,linear.source_node_count);
assert.equal(visible.coverage,linear.coverage);
assert.equal(visible.source_linear_available,linear.source_linear_available);
assert.equal(diagnostics.coverage,visible.coverage);
assert.equal(receipt.coverage,visible.coverage);
console.log(JSON.stringify({result:'PASS',required_files_verified:required.length,source_url:receipt.source_url,coverage:visible.coverage,source_linear_available:visible.source_linear_available,linear_node_count:linear.source_node_count,selected_visible_messages:visible.messages.length,counts:visible.counts,decoder:diagnostics.decoder,methods:receipt.methods,attestation:att.verification,published_commit_sha:att.published_commit_sha,output_directory:dir}));
NODE
